// Extract the binary PDF data and convert to base64 text.
// n8n stores downloaded files in $binary.data
const items = $input.all();
const results = [];

for (const item of items) {
  // Get the original filename from the trigger
  const fileName = item.json.name || 'rfp_document.pdf';

  // The binary data from Google Drive download
  const binaryData = item.binary?.data;

  if (!binaryData) {
    throw new Error('No binary data found in downloaded file');
  }

  results.push({
    json: {
      fileName,
      fileId: item.json.id,
      mimeType: binaryData.mimeType || 'application/pdf',
      fileSize: binaryData.fileSize,
      // Pass binary reference forward
    },
    binary: item.binary,
  });
}

return results;

// Clean up the raw extracted text before sending to Sellora backend.
// Removes excessive whitespace, page headers/footers noise, etc.
const items = $input.all();
const results = [];

for (const item of items) {
  let rawText = item.json.text || item.json.data || '';

  if (!rawText || rawText.trim().length < 50) {
    throw new Error(`PDF text extraction yielded too little content for file: ${item.json.fileName || 'unknown'}. The PDF may be scanned/image-based.`);
  }

  // Basic cleanup
  let cleanedText = rawText
    // Normalize line endings
    .replace(/\r\n/g, '\n')
    // Collapse 3+ blank lines into 2
    .replace(/\n{3,}/g, '\n\n')
    // Remove common PDF artifacts
    .replace(/\f/g, '\n')
    .trim();

  results.push({
    json: {
      fileName: item.json.fileName,
      fileId: item.json.fileId,
      rfpText: cleanedText,
      charCount: cleanedText.length,
      estimatedPages: Math.ceil(cleanedText.length / 3000),
    }
  });
}

return results;

// Parse and reshape the Sellora RFP API response into rows for Excel.
// Response shape (from your backend docs):
// {
//   success: true,
//   data: {
//     extractedQuestions: [...],
//     answers: [
//       {
//         question: string,
//         rewrittenQuestion: string,
//         answer: string,
//         confidence: 'HIGH' | 'MEDIUM' | 'LOW',
//         refused: boolean,
//         citations: [{ chunkId, documentId, score, text, sectionTitle }]
//       }
//     ],
//     aiInteractionId: string,
//     totalQuestions: number,
//     answeredCount: number,
//     refusedCount: number
//   }
// }

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json.data || item.json;
  const answers = data.answers || [];

  if (answers.length === 0) {
    throw new Error('Sellora returned zero answers. Check the rfpText was not empty.');
  }

  const rows = answers.map((ans, idx) => ({
    rowNumber: idx + 1,
    originalQuestion: ans.question || '',
    rewrittenQuestion: ans.rewrittenQuestion || ans.question || '',
    answer: ans.refused
      ? 'INSUFFICIENT CONTEXT — Manual review required'
      : (ans.answer || ''),
    confidence: ans.refused ? 'N/A' : (ans.confidence || 'LOW'),
    requiresReview: ans.refused ? 'YES' : 'NO',
    topCitationSection: ans.citations?.[0]?.sectionTitle || '',
    topCitationScore: ans.citations?.[0]?.score
      ? (ans.citations[0].score * 100).toFixed(1) + '%'
      : '',
    citationCount: (ans.citations || []).length,
  }));

  results.push({
    json: {
      rows,
      summary: {
        totalQuestions: data.totalQuestions || answers.length,
        answeredCount: data.answeredCount || answers.filter(a => !a.refused).length,
        refusedCount: data.refusedCount || answers.filter(a => a.refused).length,
        aiInteractionId: data.aiInteractionId || '',
      },
      // Pass through for email node
      sourceFileName: $('Clean & Validate Text').first().json.fileName,
      fileId: $('Clean & Validate Text').first().json.fileId,
    }
  });
}

return results;

// Convert answer rows into a proper spreadsheet binary.
// n8n's 'Convert to File' node or SpreadsheetFile node writes XLSX.

const item = $input.first().json;
const rows = item.rows || [];
const summary = item.summary || {};

// Build CSV-style data for the Convert to File node.
// We'll pass it as structured JSON; the next node writes it as XLSX.

const headers = [
  '#',
  'Original Question',
  'Refined Question (AI)',
  'Answer',
  'Confidence',
  'Requires Manual Review?',
  'Source Section',
  'Match Score',
  'Citations Used',
];

const dataRows = rows.map(r => ([
  r.rowNumber,
  r.originalQuestion,
  r.rewrittenQuestion,
  r.answer,
  r.confidence,
  r.requiresReview,
  r.topCitationSection,
  r.topCitationScore,
  r.citationCount,
]));

// Summary rows at the bottom
const summaryRows = [
  [],
  ['SUMMARY', '', '', '', '', '', '', '', ''],
  ['Total Questions', summary.totalQuestions, '', '', '', '', '', '', ''],
  ['Answered', summary.answeredCount, '', '', '', '', '', '', ''],
  ['Needs Review', summary.refusedCount, '', '', '', '', '', '', ''],
  ['AI Interaction ID', summary.aiInteractionId, '', '', '', '', '', '', ''],
  ['Generated by', 'Sellora AI Backend', '', '', '', '', '', '', ''],
  ['Timestamp', new Date().toISOString(), '', '', '', '', '', '', ''],
];

return [{
  json: {
    headers,
    dataRows,
    summaryRows,
    allRows: [headers, ...dataRows, ...summaryRows],
    // Metadata for email
    sourceFileName: item.sourceFileName,
    summary,
  }
}];
